func queryDB(ctx context.Context) error {
	select {
	case <-time.After(400 * time.Millisecond): // pretend the query takes 400ms
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

package main

import (
	"context"
	"fmt"
	"time"
)

func slowQuery(ctx context.Context) error {
	time.Sleep(400 * time.Millisecond)
	return nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	start := time.Now()
	err := slowQuery(ctx)
	fmt.Println(err, time.Since(start).Round(100*time.Millisecond))
}

package main

import (
	"context"
	"fmt"
	"time"
)

func fetch(ctx context.Context) string {
	select {
	case <-time.After(10 * time.Millisecond):
		return "ok"
	case <-ctx.Done():
		return ctx.Err().Error()
	}
}

func main() {
	ctx, _ := context.WithTimeout(context.Background(), time.Second)
	fmt.Println(fetch(ctx))
}
